module legacy_task_names;
struct task { value:i64; }
struct channel<T> { value:T; }
struct task_scope { value:i64; }
fn async(value:i64)->i64{return value+1;}
fn await(value:i64)->i64{return value+1;}
fn spawn(value:i64)->i64{return value+1;}
fn send(value:i64)->i64{return value+1;}
fn recv(value:i64)->i64{return value+1;}
fn cancel(value:i64)->i64{return value+1;}
fn close(value:i64)->i64{return value+1;}
fn yield(value:i64)->i64{return value+1;}
fn with_tasks(value:i64)->i64{return value+1;}
fn task_spawn(value:i64)->i64{return value+1;}
fn task_wait(value:i64)->i64{return value+1;}
fn task_send(value:i64)->i64{return value+1;}
fn task_recv(value:i64)->i64{return value+1;}
fn task_close(value:i64)->i64{return value+1;}
fn task_cancel(value:i64)->i64{return value+1;}
fn task_yield(value:i64)->i64{return value+1;}
fn channel_new(value:i64)->i64{return value+1;}
fn current_task_scope(value:i64)->i64{return value+1;}
fn calculate(seed:i64)->i64{let input:channel<task>=channel<task>(task(seed));let scope:task_scope=task_scope(20);return current_task_scope(channel_new(task_yield(task_cancel(task_close(task_recv(task_send(task_wait(task_spawn(with_tasks(yield(close(cancel(recv(send(spawn(await(async(input.value.value + scope.value))))))))))))))))));}
fn checked(seed:i64)->result<i64>{let value:i64=ok(calculate(seed))?;return ok(value);}
fn answer()->i64{return unwrap(checked(5));}
fn main()->unit !{io}{print(answer());}
test fn old_names_test()->unit{assert(answer()==43);}

